1	import { ModifiableValueType } from "../types/template/Base";
2	
3	/**
4	 * A class for managing a list of named parts with generic values.
5	 * This class provides methods for adding, removing, and querying parts,
6	 * as well as calculating the total of numerical parts.
7	 */
8	export class ModifiableValue<Field extends ModifiableValueType = ModifiableValueType> {
9	    // Use finite sentinels so priorities survive chat flag serialization.
10	    static readonly LOWER_PRIORITY = Number.MIN_SAFE_INTEGER;
11	    static readonly TOP_PRIORITY = Number.MAX_SAFE_INTEGER;
12	
13	    private readonly _field: Field;
14	
15	    get changes() {
16	        return this._field.changes;
17	    }
18	
19	    /**
20	     * Create a manager for a modifiable numeric field.
21	     * @param {Field} field - The field object containing `base`, `value`, and `changes`.
22	     */
23	    constructor(field: Field) {
24	        this._field = field;
25	    }
26	
27	    /**
28	     * Get the numeric value of the first change matching `name`.
29	     * @param {string} name - The part name to find in `changes`.
30	     * @returns {number | undefined} The value of the found part, or `undefined` if not present.
31	     */
32	    get(name: string) {
33	        return this._field.changes.find(part => part.name === name)?.value;
34	    }
35	
36	    /**
37	     * Adds a new part to the list.
38	     * @param {string} name - The change name.
39	     * @param {number} value - The numeric value for the change.
40	     * @param {CONST.ACTIVE_EFFECT_MODES} [mode=CONST.ACTIVE_EFFECT_MODES.ADD] - The change mode.
41	     * @param {number} [priority=10*mode] - Priority for ordering.
42	     */
43	    add(...args: Parameters<ModifiableValue["_createChange"]>): void {
44	        this._field.changes.push(this._createChange(...args));
45	    }
46	
47	    /**
48	     * Add a base change (uses the lowest possible priority sentinel).
49	     * @param {string} name - The base change name.
50	     * @param {number} value - The base numeric value.
51	     */
52	    addBase(name: string, value: number): void {
53	        return this.add(name, value, CONST.ACTIVE_EFFECT_MODES.ADD, ModifiableValue.LOWER_PRIORITY);
54	    }
55	
56	    /**
57	     * Adds a part with a unique name, overwriting an existing one with the same name.
58	     * @param {string} name - Unique name for the change.
59	     * @param {number | undefined | null} value - Value to set; if `null`/`undefined`, the entry will be removed.
60	     * @param {CONST.ACTIVE_EFFECT_MODES} [mode=CONST.ACTIVE_EFFECT_MODES.ADD] - Mode used when applying the change.
61	     * @param {number} [priority=10*mode] - Priority for ordering.
62	     */
63	    addUnique(
64	        name: string,
65	        value: number | undefined | null,
66	        mode: CONST.ACTIVE_EFFECT_MODES = CONST.ACTIVE_EFFECT_MODES.ADD,
67	        priority: number = 10 * mode,
68	    ): void {
69	        const index = this._field.changes.findIndex(part => part.name === name);
70	
71	        if (value != null) {
72	            const newPart = this._createChange(name, value, mode, priority);
73	            if (index !== -1) {
74	                newPart.enabled = this._field.changes[index].enabled;
75	                newPart.invalidated = this._field.changes[index].invalidated;
76	
77	                this._field.changes[index] = newPart;
78	            } else {
79	                this._field.changes.push(newPart);
80	            }
81	        } else if (index === -1) {
82	            console.warn(`Shadowrun 5e | Cannot add a part with an undefined value. Part: ${name}`);
83	        } else {
84	            this._field.changes.splice(index, 1);
85	        }
86	    }
87	
88	    /**
89	     * Add a unique base change (lowest possible priority sentinel).
90	     * @param {string} name - Name of the base change.
91	     * @param {number | undefined | null} value - Base value to set; if `null`/`undefined`, the entry will be removed.
92	     */
93	    addUniqueBase(name: string, value: number | undefined | null): void {
94	        return this.addUnique(name, value, CONST.ACTIVE_EFFECT_MODES.ADD, ModifiableValue.LOWER_PRIORITY);
95	    }
96	
97	    /**
98	     * Add or remove a unique change based on the presence of a value.
99	     * If `value` is provided, it adds/updates the change;
100	     * if `value` is falsy, it removes the change with the given name.
101	     * @param {string} name - The name of the change to add or remove.
102	     * @param {number | undefined | null} value - The value to set for the change; if falsy, the change will be removed.
103	     * @param {CONST.ACTIVE_EFFECT_MODES} [mode=CONST.ACTIVE_EFFECT_MODES.ADD] - The mode to use when adding the change.
104	     * @param {number} [priority=10*mode] - The priority to use when adding the change.
105	     */
106	    setUnique(
107	        name: string,
108	        value: number | undefined | null,
109	        mode: CONST.ACTIVE_EFFECT_MODES = CONST.ACTIVE_EFFECT_MODES.ADD,
110	        priority: number = 10 * mode,
111	    ): void {
112	        if (value) {
113	            this.addUnique(name, value, mode, priority);
114	        } else {
115	            this.remove(name);
116	        }
117	    }
118	
119	    /**
120	     * Remove all changes with the given name.
121	     * @param {string} name - Name of the part to remove from `changes`.
122	     */
123	    remove(name: string): void {
124	        this._field.changes = this._field.changes.filter(part => part.name !== name);
125	    }
126	
127	    /**
128	     * Calculate the total value by applying changes in priority order.
129	     * @param {{min?: number, max?: number}} [options] - Optional bounds to enforce on the final value.
130	     * @param {number} [options.min] - If provided, enforces a minimum value (adds an `SR5.EnforcedMinimum` change).
131	     * @param {number} [options.max] - If provided, enforces a maximum value (adds an `SR5.EnforcedMaximum` change).
132	     * @returns {number} The computed total (rounded up per SR5 rules).
133	     */
134	    calcTotal(options?: { min?: number; max?: number }): number {
135	        this._field.value = this._field.base;
136	
137	        this._field.changes.sort((a, b) => b.priority - a.priority);
138	        for (let i = 0; i < this._field.changes.length; i++) {
139	            const change = this._field.changes[i];
140	            change.invalidated = false;
141	
142	            if (!change.enabled) continue;
143	
144	            switch (change.mode) {
145	                case CONST.ACTIVE_EFFECT_MODES.ADD:
146	                case CONST.ACTIVE_EFFECT_MODES.CUSTOM:
147	                    this._field.value += change.value;
148	                    break;
149	                case CONST.ACTIVE_EFFECT_MODES.MULTIPLY:
150	                    this._field.value *= change.value;
151	                    break;
152	                case CONST.ACTIVE_EFFECT_MODES.OVERRIDE:
153	                    this._field.value = change.value;
154	                    this._markPreviousChangesMasked(i);
155	                    break;
156	                case CONST.ACTIVE_EFFECT_MODES.UPGRADE:
157	                    if (this._field.value < change.value) {
158	                        this._field.value = change.value;
159	                        this._markPreviousChangesMasked(i);
160	                    } else {
161	                        change.invalidated = true;
162	                    }
163	                    break;
164	                case CONST.ACTIVE_EFFECT_MODES.DOWNGRADE:
